const $=s=>document.querySelector(s), KEY='campus-pulse-v2', H=3600000;
const areas={'Academic block':[78.5716,17.5445],'Auditorium':[78.57067825,17.54538047],'Rock Garden':[78.5732,17.5447],'Sports area (illustrative)':[78.57448405,17.5437066]}, campusRing=CAMPUS_BOUNDARY.geometry.coordinates[0], bounds=[[Math.min(...campusRing.map(c=>c[0])),Math.min(...campusRing.map(c=>c[1]))],[Math.max(...campusRing.map(c=>c[0])),Math.max(...campusRing.map(c=>c[1]))]];
const templates=[['Build your first web app','Workshop','Academic block','Sample room: Block E · Floor 1 · E-101','Sample coding group','A guided, beginner-friendly workshop. Bring a laptop and leave with a small working web app.',-1,3],['An evening of acoustic music','Fun','Rock Garden','Garden entrance · approximate meeting point','Sample music circle','An unplugged jam. Bring an instrument, or just come listen.',2,4],['Ideas worth sharing','Speaker','Auditorium','Main foyer · illustrative meeting point','Sample speaker series','A visiting researcher shares their work, followed by an open Q&A. Everyone is welcome.',22,24],['Anyone up for a quick game?','Fun','Sports area (illustrative)','Approximate sports-area pin · confirm with host','Sample student group','A casual game meetup. The host will confirm the playing area.',-1,2]];
const EVENT_TYPES = ['Speaker','Workshop','Contest','Fun','Other','Empty classroom'];
const makeSeed=(t,i)=>({id:i+1,title:t[0],category:t[1],area:t[2],room:t[3],host:t[4],description:t[5],start:new Date(Date.now()+t[6]*H).toISOString(),end:new Date(Date.now()+t[7]*H).toISOString(),coords:areas[t[2]],mine:false});
const extraSeeds=[{id:5,title:'Campus coding sprint',category:'Contest',area:'Academic block',room:'New academic block · sample classroom',host:'Sample programming club',description:'A friendly team coding contest. Beginners can join too.',start:new Date(Date.now()+H).toISOString(),end:new Date(Date.now()+4*H).toISOString(),coords:[78.56971119,17.54590356],mine:false},{id:6,title:'Books, notes & little things',category:'Other',area:'Custom pin',room:'Connaught Place · sample meetup spot',host:'Sample student collective',description:'An informal book and notes exchange. Drop by with something to share.',start:new Date(Date.now()-H).toISOString(),end:new Date(Date.now()+3*H).toISOString(),coords:[78.5756,17.5420],mine:false}];
let state;try{state=JSON.parse(localStorage.getItem(KEY))}catch{}if(!state||!Array.isArray(state.events))state={events:[...templates.map(makeSeed),...extraSeeds],rsvps:[],reports:[]};
for(const e of state.events){if(!e.mine&&e.id>=1&&e.id<=4){const fresh=makeSeed(templates[e.id-1],e.id-1);Object.assign(e,{title:fresh.title,category:fresh.category,host:fresh.host,description:fresh.description,coords:fresh.coords})}else{e.category=({Tech:'Workshop',Social:'Fun',Sports:'Fun'})[e.category]||e.category;if(!EVENT_TYPES.includes(e.category))e.category='Other'}}
for(const e of extraSeeds)if(!state.events.some(x=>x.id===e.id))state.events.push(e);

let filter='All',view='Explore',selected=null,map,markers=[],picking=false,draftPoint=null,satellite=false,showEmptyClassrooms=false;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeLink=s=>{try{let u=new URL(s);return ['http:','https:'].includes(u.protocol)?u.href:''}catch{return ''}};
const inside=c=>{if(!Array.isArray(c)||!Number.isFinite(c[0])||!Number.isFinite(c[1]))return false;const [x,y]=c;let hit=false;for(let i=0,j=campusRing.length-1;i<campusRing.length;j=i++){const [xi,yi]=campusRing[i],[xj,yj]=campusRing[j];const cross=(x-xi)*(yj-yi)-(y-yi)*(xj-xi);if(Math.abs(cross)<1e-12&&x>=Math.min(xi,xj)&&x<=Math.max(xi,xj)&&y>=Math.min(yi,yj)&&y<=Math.max(yi,yj))return true;if((yi>y)!==(yj>y)&&x<(xj-xi)*(y-yi)/(yj-yi)+xi)hit=!hit}return hit};
const ongoing=e=>new Date(e.start)<=new Date()&&new Date(e.end)>new Date();
const date=s=>new Date(s).toLocaleString('en-IN',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}), time=e=>ongoing(e)?'Happening now':date(e.start);
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4000)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('Browser storage unavailable. Changes last for this session.')}}
function shownEvents(){let q=$('#search').value.toLowerCase();return state.events.filter(e=>inside(e.coords)&&(e.category!=='Empty classroom'||showEmptyClassrooms)&&new Date(e.end)>new Date()&&(view!=='Mine'||e.mine)&&(view!=='RSVPs'||state.rsvps.includes(e.id))&&(filter==='All'||(filter==='Now'?ongoing(e):e.category===filter))&&[e.title,e.area,e.host,e.room].join(' ').toLowerCase().includes(q))}
function setClassroomVisibility(visible){showEmptyClassrooms=visible;$('#toggleClassrooms').setAttribute('aria-pressed',String(visible));if(!visible&&filter==='Empty classroom'){filter='All';document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===filter))}render()}
function selectEvent(id){selected=id;render();let e=state.events.find(e=>e.id===id);if(map&&e){map.easeTo({center:e.coords,duration:400});if(innerWidth<=760)$('#campusMap').scrollIntoView({behavior:'smooth',block:'center'})}}
function render(){let shown=shownEvents();$('#count').textContent=shown.length+' '+(shown.length===1?'activity':'activities');$('.list-heading h2').textContent=view==='Mine'?'My events':view==='RSVPs'?'My RSVPs':'Around campus';$('#events').innerHTML=shown.length?shown.map(e=>`<button data-category="${esc(e.category)}" class="event ${selected===e.id?'selected':''}" data-id="${e.id}"><div class="event-top"><span class="tag">${esc(e.category)}</span><span>${esc(time(e))}</span></div><h3>${esc(e.title)}<span class="event-arrow" aria-hidden="true">↗</span></h3><p>⌖ ${esc(e.area)}</p><p class="host">By ${esc(e.host)}${state.rsvps.includes(e.id)?' · ✓ Going':''}</p></button>`).join(''):`<p class="empty">${view==='Mine'?'Your posted events will appear here.':view==='RSVPs'?'Open an activity and tap RSVP to save it here.':'No matching activities. Try another filter.'}</p>`;
if(map){markers.forEach(m=>m.remove());markers=shown.map(e=>{let b=document.createElement('button');b.className='geo-pin '+(e.id===selected?'selected':'');b.innerHTML="<svg viewBox=\"0 0 32 42\" aria-hidden=\"true\" focusable=\"false\"><path d=\"M16 1C7.72 1 1 7.72 1 16c0 10.9 15 25 15 25s15-14.1 15-25C31 7.72 24.28 1 16 1Z\"/><circle cx=\"16\" cy=\"16\" r=\"5\"/></svg>";b.title=e.category+': '+e.title;b.setAttribute('aria-pressed',String(e.id===selected));b.setAttribute('aria-label',e.title);b.dataset.category=e.category;b.onclick=ev=>{ev.stopPropagation();selectEvent(e.id)};return new maplibregl.Marker({element:b,anchor:'bottom'}).setLngLat(e.coords).addTo(map)})}
let e=shown.find(e=>e.id===selected);$('#detail').innerHTML=e?`<button class="close" id="closeDetail" aria-label="Close activity details">×</button><span class="badge">${esc(e.category)} · ${e.mine?'YOUR EVENT':'SAMPLE EVENT'}</span><h2>${esc(e.title)}</h2><p>◷ ${esc(time(e))}<br>Ends ${esc(date(e.end))}</p><p><b>⌖ ${esc(e.area)}</b><br>${esc(e.room)}</p><p>${esc(e.description)}</p><p>Hosted by <b>${esc(e.host)}</b></p>${safeLink(e.link)?`<a href="${esc(safeLink(e.link))}" target="_blank" rel="noopener noreferrer">Open activity link ↗</a>`:''}<div class="detail-actions"><button class="primary" id="rsvp" aria-pressed="${state.rsvps.includes(e.id)}">${state.rsvps.includes(e.id)?'✓ Going · Undo RSVP':'RSVP · I’m going'}</button>${e.mine?'<button class="text-button" id="cancelEvent">Cancel event</button>':'<button class="text-button" id="reportEvent">Report event</button>'}</div><p class="footnote">RSVPs and reports are local demo actions.</p>`:'';
document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>selectEvent(Number(b.dataset.id)));if(e){$('#closeDetail').onclick=()=>{selected=null;render()};$('#rsvp').onclick=()=>{state.rsvps=state.rsvps.includes(e.id)?state.rsvps.filter(id=>id!==e.id):[...state.rsvps,e.id];save();render()};if($('#cancelEvent'))$('#cancelEvent').onclick=()=>{state.events=state.events.filter(item=>item.id!==e.id);state.rsvps=state.rsvps.filter(id=>id!==e.id);save();selected=null;render();toast('Your event was removed from this demo.')};if($('#reportEvent'))$('#reportEvent').onclick=()=>{if(!state.reports.some(r=>r.event===e.id)){state.reports.push({event:e.id,reason:'Flagged for review',created:new Date().toISOString()});save()}toast('Report saved locally. This demo has no moderation service.')}}}
function fit(){if(map)map.fitBounds(bounds,{padding:innerWidth<=760?{top:145,bottom:95,left:25,right:45}:{top:130,bottom:90,left:45,right:70},duration:450,bearing:0,pitch:0})}
function initMap(){try{map=new maplibregl.Map({container:'campusMap',style:{version:8,glyphs:CAMPUS_STREET_STYLE.glyphs,sources:{...CAMPUS_STREET_STYLE.sources,satellite:{type:'raster',tiles:['https://services.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}'],tileSize:256,maxzoom:19,attribution:'Imagery © Esri, Maxar, Earthstar Geographics, and the GIS User Community'}},layers:[...CAMPUS_STREET_STYLE.layers,{id:'satellite',type:'raster',source:'satellite',layout:{visibility:'none'}}]},center:[78.5732,17.5454],zoom:16,minZoom:12.5,maxZoom:20,maxBounds:[[78.558,17.533],[78.59,17.558]],bearing:0,pitch:0,dragRotate:false,pitchWithRotate:false,touchPitch:false,attributionControl:false});map.touchZoomRotate.disableRotation();map.addControl(new maplibregl.NavigationControl({showCompass:false}),'top-right');map.addControl(new maplibregl.ScaleControl({maxWidth:100}),'bottom-left');map.addControl(new maplibregl.AttributionControl({compact:true}),'bottom-right');
map.on('load',()=>{map.addSource('campus-perimeter',{type:'geojson',data:CAMPUS_BOUNDARY,attribution:'© <a href="https://www.openstreetmap.org/copyright" target="_blank">OpenStreetMap contributors</a>'});map.addSource('outside-campus',{type:'geojson',data:{type:'Feature',properties:{},geometry:{type:'Polygon',coordinates:[[[78.4,17.4],[78.8,17.4],[78.8,17.7],[78.4,17.7],[78.4,17.4]],campusRing]}}});map.addLayer({id:'outside-campus',type:'fill',source:'outside-campus',paint:{'fill-color':'#fff3e4','fill-opacity':1}});map.addLayer({id:'campus-perimeter',type:'line',source:'campus-perimeter',paint:{'line-color':'#c5a987','line-width':1.5,'line-opacity':0.9}});fit();render()});map.on('error',()=>{$('#mapStatus').textContent='Map imagery unavailable? Try the other map layer.'});map.on('idle',()=>{if(map.areTilesLoaded())$('#mapStatus').textContent=''});map.on('moveend',()=>{$('#campusMap').setAttribute('aria-label',`Zoomable campus map · zoom ${map.getZoom().toFixed(1)} · north up`)});map.on('click',e=>{if(!picking)return;let point=[e.lngLat.lng,e.lngLat.lat];if(!inside(point)){toast('Choose a point inside the campus boundary.');return}draftPoint=point;stopPicking();$('#postForm').elements.area.value='Custom pin';$('#locationStatus').textContent='✓ Exact map point selected. Add building and room details below.';$('#postDialog').showModal()});new ResizeObserver(()=>map.resize()).observe($('#campusMap'));render()}catch(error){console.error('Campus map initialization failed:',error);$('#mapStatus').textContent='The map needs WebGL support. Activity cards are still available.';$('#pickLocation').disabled=true;$('#chooseMap').disabled=true}}
function stopPicking(){picking=false;$('#mapHint').textContent='Drag to explore · Pinch or use + / − to zoom';$('#pickLocation').textContent='＋ Drop a pin';$('#campusMap').classList.remove('picking')}
function startPicking(){if(!map)return;$('#postDialog').close();selected=null;render();picking=true;$('#mapHint').textContent='Tap a point inside campus · Esc to cancel';$('#pickLocation').textContent='Cancel pin placement';$('#campusMap').classList.add('picking');$('#campusMap').scrollIntoView({behavior:'smooth',block:'center'})}
function localInput(d){return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}
function resetDraft(){draftPoint=null;$('#postForm').reset();$('#postForm').elements.start.value=localInput(new Date());$('#postForm').elements.end.value=localInput(new Date(Date.now()+H));$('#locationStatus').textContent='Choose an area, or pick a point on the map.'}
$('#add').onclick=()=>{stopPicking();resetDraft();$('#postDialog').showModal()};$('#pickLocation').onclick=()=>{if(picking)stopPicking();else{resetDraft();startPicking()}};$('#chooseMap').onclick=startPicking;document.addEventListener('keydown',e=>{if(e.key==='Escape')stopPicking()});$('#fitCampus').onclick=fit;
$('#basemap').onclick=()=>{if(!map||!map.isStyleLoaded())return;satellite=!satellite;$('.place-legend').style.display=satellite?'none':'';map.setLayoutProperty('satellite','visibility',satellite?'visible':'none');for(const layer of CAMPUS_STREET_STYLE.layers)map.setLayoutProperty(layer.id,'visibility',satellite?'none':'visible');$('#basemap').textContent=satellite?'Satellite':'Street';$('#basemap').setAttribute('aria-pressed',String(satellite));$('#mapStatus').textContent=''};
$('#postForm').elements.area.onchange=e=>{draftPoint=null;$('#locationStatus').textContent=e.target.value==='Custom pin'?'Pick a point on the map before posting.':'Approximate area pin selected. Add exact room details below.'};
$('#postForm').onsubmit=e=>{e.preventDefault();let data=Object.fromEntries(new FormData(e.target)),start=new Date(data.start),end=new Date(data.end);if(end<=start||end<=new Date()){toast('Choose an end time after the start and in the future.');return}let coords=draftPoint||areas[data.area];if(!inside(coords)){toast('Pick a location inside the campus boundary first.');return}if(data.link&&!safeLink(data.link)){toast('Use an http or https activity link.');return}let item={...data,id:Date.now(),start:start.toISOString(),end:end.toISOString(),coords,mine:true};state.events.unshift(item);save();view='Mine';filter='All';$('#search').value='';document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===filter));$('#postDialog').close();selectEvent(item.id);toast(item.category==='Empty classroom'&&!showEmptyClassrooms?'Classroom saved. Turn on Empty classrooms in the map key to show it.':'Activity added to My events on this device.');resetDraft()};
$('#toggleClassrooms').onclick=()=>setClassroomVisibility(!showEmptyClassrooms);
$('#search').oninput=render;document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;if(filter==='Empty classroom'){showEmptyClassrooms=true;$('#toggleClassrooms').setAttribute('aria-pressed','true')}document.querySelectorAll('[data-filter]').forEach(c=>c.classList.toggle('active',c===b));render()});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;document.querySelectorAll('[data-view]').forEach(c=>c.classList.toggle('active',c===b));render()});$('#about').onclick=()=>$('#aboutDialog').showModal();document.querySelectorAll('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());for(const e of state.events){if(!e.mine&&e.id===4){e.coords=areas['Sports area (illustrative)'];e.room='Old Football ground · sample meeting point'}}resetDraft();render();initMap();

setInterval(render,60000);
